/**
 * Unit tests for CategoryPlot.removeDomainMarker.
 */
public class CategoryPlot_removeDomainMarker_TriageGen2Test {

    private CategoryPlot plot;
    private Marker marker;
    private ArrayList<Marker> foregroundMarkers;
    private ArrayList<Marker> backgroundMarkers;

    @Before
    public void setUp() throws Exception {
        plot = new CategoryPlot();
        marker = mock(Marker.class);

        // Initialize the internal maps using reflection since they are private
        foregroundMarkers = new ArrayList<>();
        backgroundMarkers = new ArrayList<>();

        Map<Integer, ArrayList> fgMap = new HashMap<>();
        Map<Integer, ArrayList> bgMap = new HashMap<>();

        fgMap.put(0, foregroundMarkers);
        bgMap.put(0, backgroundMarkers);

        setPrivateField(plot, "foregroundDomainMarkers", fgMap);
        setPrivateField(plot, "backgroundDomainMarkers", bgMap);
    }

    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_Notify() {
        foregroundMarkers.add(marker);

        // Testing removal from foreground with notify = true
        boolean result = plot.removeDomainMarker(0, marker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed", result);
        assertFalse("Marker list should be empty", foregroundMarkers.contains(marker));
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_NoNotify() {
        foregroundMarkers.add(marker);

        // Testing removal from foreground with notify = false
        boolean result = plot.removeDomainMarker(0, marker, Layer.FOREGROUND, false);

        assertTrue("Marker should be removed", result);
        assertFalse("Marker list should be empty", foregroundMarkers.contains(marker));
    }

    @Test
    public void testRemoveDomainMarker_Background_Success_Notify() {
        backgroundMarkers.add(marker);

        // Testing removal from background with notify = true
        boolean result = plot.removeDomainMarker(0, marker, Layer.BACKGROUND, true);

        assertTrue("Marker should be removed", result);
        assertFalse("Marker list should be empty", backgroundMarkers.contains(marker));
    }

    @Test
    public void testRemoveDomainMarker_Background_Success_NoNotify() {
        backgroundMarkers.add(marker);

        // Testing removal from background with notify = false
        boolean result = plot.removeDomainMarker(0, marker, Layer.BACKGROUND, false);

        assertTrue("Marker should be removed", result);
        assertFalse("Marker list should be empty", backgroundMarkers.contains(marker));
    }

    @Test
    public void testRemoveDomainMarker_NotFound() {
        // List is empty, trying to remove a marker that doesn't exist
        boolean resultForeground = plot.removeDomainMarker(0, marker, Layer.FOREGROUND, true);
        boolean resultBackground = plot.removeDomainMarker(0, marker, Layer.BACKGROUND, true);

        assertFalse("Should return false when marker not found in foreground", resultForeground);
        assertFalse("Should return false when marker not found in background", resultBackground);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveDomainMarker_InvalidIndex() {
        // This will trigger an exception when accessing the map with a non-existent key
        plot.removeDomainMarker(99, marker, Layer.FOREGROUND, true);
    }
}
